"""Deterministic developer authoring, never executed by installed content packs."""
import json, pathlib, random
ROOT=pathlib.Path(__file__).resolve().parents[1]
P='jp.exam.chemistry.organic-polymer'
units=[]; nodes=[]; questions=[]; reactions=[]
def U(key,title,stage,summary):
    units.append(dict(id=f'{P}.unit.{key}',title=title,stage=stage,summary=summary))
def N(key,unit,title,core,example,caution,prompt,answer,wrong1,wrong2,why,prereqs=(),difficulty=1,dimension='knowledge',aliases=()):
    nid=f'{P}.node.{key}'
    nodes.append(dict(id=nid,unitId=f'{P}.unit.{unit}',title=title,dimension=dimension,
      prerequisites=[f'{P}.node.{x}' for x in prereqs],lesson=dict(core=core,example=example,caution=caution)))
    choices=[dict(id='a',text=answer,feedback=why),
      dict(id='b',text=wrong1,misconception=f'{P}.misconception.{key}.b',feedback=f'「{wrong1}」を選ぶ前に確認：{caution}'),
      dict(id='c',text=wrong2,misconception=f'{P}.misconception.{key}.c',feedback=f'この問題の条件に合わせて考えると、{why}')]
    random.Random(key).shuffle(choices)
    common=dict(nodeIds=[nid],difficulty=difficulty,hints=[f'まず「{title}」で注目する構造・条件を整理しよう。',core,f'具体例：{example}'],explanation=f'{why}\n\n考え方：{core}\n注意：{caution}',sourceId='original')
    questions.append(dict(id=f'{P}.q.{key}.choice',kind='choice',prompt=prompt,choices=choices,answer='a',**common))
    if aliases:
      questions.append(dict(id=f'{P}.q.{key}.recall',kind='text',prompt=prompt+'\n名称・用語を入力してください。',answer=answer,aliases=list(aliases),**common))
def Q(key,node,prompt,answer,unit,explanation,hints,difficulty=2,tolerance=0):
    q=dict(id=f'{P}.q.{key}',nodeIds=[f'{P}.node.{node}'],kind='numeric',difficulty=difficulty,prompt=prompt,answer=answer,tolerance=tolerance,explanation=explanation,hints=hints,sourceId='original')
    if unit:q['unit']=unit
    questions.append(q)
def R(key,fr,to,condition,node,typ):
    reactions.append({'id':f'{P}.reaction.{key}','from':fr,'to':to,'condition':condition,'nodeId':f'{P}.node.{node}','type':typ})

